export const RECIPES_DATA: RecipeData[] = [{"id":"brand-listening","title":"Watch what the web says about a brand","when":["brand mentions","what are people saying about our brand","brand health or sentiment over time","monitor mentions of a company or product"],"inputs":[{"name":"brand","description":"The brand or product name","example":"notion"},{"name":"start_date","description":"First day of the window, YYYY-MM-DD","example":"2026-09-01"}],"steps":[{"id":"mentions","endpoint":"prism/brand-mentions","params":{"keyword":"{brand}","date_from":"{start_date}","include":"digest"},"note":"One call returns the mention volume trend, the sentiment split, top sources and recent mentions; include=digest adds a written summary."}],"size":{"description":"one brand, one window","items":1},"cheaper":[{"endpoint":"search/multi","why":"Native search results from the platforms you name, priced per platform page, when you need this week's social posts rather than a trend."}],"deeper":[{"endpoint":"prism/share-of-voice","why":"The same read for two to five competing brands at once, as a share of voice."}],"pitfalls":["prism/brand-mentions reads a web citation index (news, blogs, forums, shops) that lags the live web by days; it is not a live social search.","date_from is required, as YYYY-MM-DD.","A brand name that is also a common word (Notion, Apple) collides with other meanings: pass brand_description, and read each recent mention's about_brand probability.","Mentions of one account (replies, tags, retweets) are a different job: use prism/mentions with the handle."],"decision_table":[{"option":"Trend, sentiment and recent mentions of one brand on the web","endpoint":"prism/brand-mentions","best_for":"A brand-health read over a date window, with a written digest","cost":"flat per call"},{"option":"Posts and replies that mention one account or link one URL","endpoint":"prism/mentions","best_for":"Who is talking to or about a handle on X and Reddit (Instagram tags opt-in)","cost":"per search page read; a page with no verified row is refunded"},{"option":"Share of voice across competing brands","endpoint":"prism/share-of-voice","best_for":"Comparing two to five brands on web and social reach","cost":"per brand; dropping the social leg halves it"},{"option":"Raw web citations with per-mention sentiment","endpoint":"content_analysis/search","best_for":"Exporting the individual web mentions behind a trend, paginated","cost":"flat per call"},{"option":"Each platform's own search, in one call","endpoint":"search/multi","best_for":"Recent social posts from the platforms you name, with since= for a window","cost":"per page, per platform, at each platform's own price"},{"option":"Ranked and clustered research answer across many sources","endpoint":"search/everywhere","best_for":"A one-off overview with real comments attached, when you do not know which platforms matter","cost":"flat per call"},{"option":"One platform's native search","endpoint":"reddit/search","best_for":"Depth on one platform with its own filters and paging (also twitter/search/tweets, tiktok/search)","cost":"per page"}],"cost":{"rows":[{"ref":"mentions","id":"prism/brand-mentions","runs":1,"hold_total":50}],"total":{"hold":50,"expected_min":50,"expected_max":50,"exact":true,"floor":false},"scaled":false}},{"id":"brand-chatter-on-chosen-platforms","title":"This week's posts about a brand on the platforms you name","when":["Reddit and X chatter about a brand this week","what are people posting about us on TikTok and Instagram","recent social posts mentioning a product"],"inputs":[{"name":"brand","description":"The brand or product name","example":"Notion"},{"name":"start_date","description":"Keep only posts on or after this day, YYYY-MM-DD","example":"2026-09-25"}],"steps":[{"id":"posts","endpoint":"search/multi","params":{"query":"{brand}","platforms":"reddit,twitter","since":"{start_date}"},"note":"Each platform runs its own search and is billed as a direct call; data.sources reports each platform's rows, charge and next_cursor."}],"size":{"description":"one page from each of two platforms","items":40},"cheaper":[{"endpoint":"reddit/search","why":"One platform only, one page, when the user named a single platform."}],"deeper":[{"endpoint":"search/everywhere","why":"A ranked, clustered answer across many more sources, at a much higher flat price."}],"pitfalls":["Name the platforms: the default set is TikTok, Instagram, YouTube, Reddit and Threads, so X is missing unless you ask for twitter.","X has no date parameter. search/multi turns since= into the since: operator for you; calling twitter/search/tweets directly, put since:YYYY-MM-DD inside query.","search/multi does not page itself: continue one platform on its own endpoint with data.sources.<platform>.next_cursor as cursor.","prism/brand-mentions and search/everywhere are not this job: they cost far more and do not limit the results to the platforms you named."],"cost":{"rows":[{"ref":"posts","id":"search/multi","runs":1,"hold_total":0},{"ref":"posts (reddit leg)","id":"reddit/search","runs":1,"hold_total":1},{"ref":"posts (twitter leg)","id":"twitter/search/tweets","runs":1,"hold_total":1}],"total":{"hold":2,"expected_min":0,"expected_max":2,"exact":true,"floor":false},"scaled":false}},{"id":"account-mentions","title":"Who mentions or replies to an account","when":["who is talking about @handle","find replies and tags of our account","posts that link to our website"],"inputs":[{"name":"handle","description":"The account handle, with or without @","example":"nasa"},{"name":"start_date","description":"Keep only rows on or after this day, YYYY-MM-DD","example":"2026-09-01"}],"steps":[{"id":"mentions","endpoint":"prism/mentions","params":{"handle":"{handle}","since":"{start_date}"},"note":"Searches X and Reddit by default; each kept row says whether it is a reply, retweet, mention or tag."}],"size":{"description":"first page of each default search","items":3},"deeper":[{"endpoint":"prism/brand-mentions","why":"Mentions of the brand name across the web index, with a trend and sentiment, rather than of the handle."}],"pitfalls":["Facebook, Threads and TikTok are accepted in platforms but not searched; add instagram to platforms for posts that tag the handle.","Pass url= instead of handle to find posts that link to a page, and add web to platforms for web pages that contain the link.","The account's own posts are dropped unless include_self=true."],"cost":{"rows":[{"ref":"mentions","id":"prism/mentions","runs":1,"hold_total":3}],"total":{"hold":3,"expected_min":1,"expected_max":3,"exact":true,"floor":false},"scaled":false}},{"id":"share-of-voice","title":"Share of voice between competing brands","when":["share of voice for us vs competitors","which brand gets talked about most","compare mention volume across brands"],"inputs":[{"name":"brands","description":"Two to five brand names, comma-separated","example":"notion,coda,airtable"},{"name":"start_date","description":"First day of the window, YYYY-MM-DD","example":"2026-07-01"}],"steps":[{"id":"sov","endpoint":"prism/share-of-voice","params":{"brands":"{brands}","date_from":"{start_date}"}}],"size":{"description":"three brands with the social leg","items":3},"cheaper":[{"endpoint":"prism/brand-mentions","why":"One brand's web trend and sentiment, when you do not need the comparison."}],"pitfalls":["This is the most expensive composite: price it as number of brands times the per-brand price before you send it.","Drop social from include for the web-only read at half the per-brand price.","The emotion overlay is third-party sentiment that is not scoped to your date window; methodology.sentiment_provenance says so.","Pass brand_descriptions when a brand name is also a common word."],"cost":{"rows":[{"ref":"sov","id":"prism/share-of-voice","runs":1,"hold_total":120}],"total":{"hold":120,"expected_min":20,"expected_max":120,"exact":true,"floor":false},"scaled":false}},{"id":"topic-across-platforms","title":"Search a topic on several platforms at once","when":["find TikTok, Instagram and YouTube posts about a topic","search a hashtag or keyword everywhere","what content exists about a trend"],"inputs":[{"name":"topic","description":"The topic or keyword","example":"matcha latte"}],"steps":[{"id":"search","endpoint":"search/multi","params":{"query":"{topic}","platforms":"tiktok,instagram,youtube","relevance":"filter"},"note":"relevance=filter drops posts that share the words but are about something else."}],"size":{"description":"one page from each of three platforms","items":60},"deeper":[{"endpoint":"search/everywhere","why":"Ranked and clustered across many sources, with top comments, for a research overview."}],"pitfalls":["A filtered page can hold fewer rows than an unfiltered one; the dropped ids are listed in data.relevance.dropped_ids.","Platform filters pass through with a prefix, for example tiktok.region=US or youtube.uploadDate=this_week.","Rows keep each platform's own order; there is no cross-platform ranking here."],"cost":{"rows":[{"ref":"search","id":"search/multi","runs":1,"hold_total":0},{"ref":"search (tiktok leg)","id":"tiktok/search","runs":1,"hold_total":1},{"ref":"search (instagram leg)","id":"instagram/search/reels","runs":1,"hold_total":1},{"ref":"search (youtube leg)","id":"youtube/search","runs":1,"hold_total":1}],"total":{"hold":3,"expected_min":0,"expected_max":3,"exact":true,"floor":false},"scaled":false}},{"id":"tweets-for-a-keyword-at-scale","title":"Collect thousands of tweets for a keyword","when":["cost of 10k tweets for a keyword","download all tweets mentioning a term","export tweets about a topic to CSV"],"inputs":[{"name":"keyword","description":"Keyword or phrase; X operators allowed","example":"nvidia"}],"steps":[{"id":"tweets","endpoint":"twitter/search/tweets","params":{"query":"{keyword}","sort":"latest","max_pages":"5"},"repeat":"until_n_items","note":"max_pages=5 makes each call walk up to five pages and return them together; the cursor it returns continues from the last page read."}],"size":{"description":"ten thousand tweets","items":10000},"pitfalls":["Billing is per page of about twenty tweets, not per call: quote pages (N / 20) before you start, and expect short pages to raise the count.","max_pages caps at five per call, so a large job is many calls; it does not change the price per page.","There is no date parameter: put since:YYYY-MM-DD and until:YYYY-MM-DD inside query."],"cost":{"rows":[{"ref":"tweets","id":"twitter/search/tweets","runs":1,"hold_total":1}],"total":{"hold":1,"expected_min":1,"expected_max":1,"exact":false,"floor":false},"scaled":false}},{"id":"buying-signals","title":"Find posts from people ready to buy","when":["find people looking for a product like ours","purchase intent posts on Reddit","leads from social conversations"],"inputs":[{"name":"category","description":"The product category, as a buyer would phrase it","example":"best crm for startups"}],"steps":[{"id":"posts","endpoint":"reddit/search","params":{"query":"{category}","label":"intent","relevance":"filter"},"note":"Each post carries computed.labels.intent; relevance=filter drops posts that are not about the category."}],"size":{"description":"one page of posts","items":25},"deeper":[{"endpoint":"prism/comment-leads","why":"Buyer leads from the comments under the posts a search returns, opening only the posts worth opening."}],"pitfalls":["The default intent label is free; adding offer= (what you sell) makes it a paid, sharper judgment.","relevance=filter can return a shorter page; the dropped ids are listed in data.relevance.dropped_ids, and pagination is unchanged."],"cost":{"rows":[{"ref":"posts","id":"reddit/search","runs":1,"hold_total":1}],"total":{"hold":1,"expected_min":1,"expected_max":1,"exact":true,"floor":false},"scaled":false}},{"id":"forum-discussions","title":"Forum threads about a topic, with top replies","when":["what do Reddit and Hacker News say about X","forum discussions about a product","community opinions with the best replies"],"inputs":[{"name":"topic","description":"The topic to look up","example":"vector databases"}],"steps":[{"id":"threads","endpoint":"search/forums","params":{"query":"{topic}"},"note":"Fuses Reddit, Hacker News and Korean forums, and attaches top comments to the leading threads."}],"size":{"description":"one fused page of threads","items":30},"cheaper":[{"endpoint":"reddit/search","why":"Reddit only, one page, no comment enrichment."}],"deeper":[{"endpoint":"search/everywhere","why":"Adds video, social and web sources to the forum threads."}],"pitfalls":["Each items[].top_comments[] row has its body in excerpt, not text, clipped on a word boundary (truncated: true when cut).","Korean forum threads come back without comments; they have no comment endpoint."],"cost":{"rows":[{"ref":"threads","id":"search/forums","runs":1,"hold_total":10}],"total":{"hold":10,"expected_min":10,"expected_max":10,"exact":true,"floor":false},"scaled":false}},{"id":"news-coverage","title":"News coverage of a topic","when":["latest news about a company","press coverage this week","headlines mentioning a topic"],"inputs":[{"name":"topic","description":"The topic or company","example":"OpenAI"}],"steps":[{"id":"news","endpoint":"google_news/search","params":{"keyword":"{topic}","time_range":"week"}}],"size":{"description":"one call at the default depth","items":10},"deeper":[{"endpoint":"search/news","why":"One query localised and fanned out across several countries and two news indexes."},{"endpoint":"prism/earned-media","why":"Earned media coverage of a brand against a competitor, with domain authority."}],"pitfalls":["google_news/search takes keyword, not query, and has no next page: depth (multiples of ten) sets how many articles one call returns.","For a listed company's headlines, finance/news takes the ticker directly and is more precise."],"cost":{"rows":[{"ref":"news","id":"google_news/search","runs":1,"hold_total":1}],"total":{"hold":1,"expected_min":1,"expected_max":1,"exact":true,"floor":false},"scaled":false}},{"id":"find-creators-in-a-niche","title":"Find creators in a niche","when":["find influencers who post about skincare","creators in a niche with over 50k followers","influencer discovery for a campaign"],"inputs":[{"name":"niche","description":"The niche, in the words creators use","example":"skincare routine"},{"name":"min_followers","description":"Follower floor","example":"50000"}],"steps":[{"id":"creators","endpoint":"search/creators","params":{"query":"{niche}","sources":"tiktok,instagram","min_followers":"{min_followers}"},"note":"One ranked list across the platforms in sources; YouTube, X and Facebook are opt-in."}],"size":{"description":"one fused list","items":1},"deeper":[{"endpoint":"prism/creator-vet","why":"Vet each shortlisted creator before you reach out."}],"pitfalls":["search/creators has no country filter: for creators from one market use instagram/search/reels with country= or tiktok/search/users with country=.","Pass brief= (what you are looking for) to re-rank creators who post about it above brands, shops and repost pages; it adds a small refundable charge."],"cost":{"rows":[{"ref":"creators","id":"search/creators","runs":1,"hold_total":10}],"total":{"hold":10,"expected_min":10,"expected_max":10,"exact":true,"floor":false},"scaled":false}},{"id":"instagram-creators-by-country","title":"Instagram creators from one country about a topic","when":["German Instagram creators about matcha","Instagram influencers in Spain over 50k followers","local creators in one market"],"inputs":[{"name":"topic","description":"The topic, ideally as locals phrase it","example":"matcha"},{"name":"country","description":"Market code: ES, MX, DE, BR, KR or FR","example":"DE"}],"steps":[{"id":"reels","endpoint":"instagram/search/reels","params":{"query":"{topic}","country":"{country}"},"note":"Keeps only reels whose creator declares that market, and fills post.ext.author_country and post.ext.author_followers; filter on author_followers yourself for a follower floor."}],"size":{"description":"one page of reels with each creator looked up","items":30},"cheaper":[{"endpoint":"search/creators","why":"Cross-platform creator search with min_followers, when the country does not matter."}],"pitfalls":["country= supports ES, MX, DE, BR, KR and FR only; any other code is a free 400.","Without country= or include=creator, post.ext.author_followers is null, so a follower floor cannot be applied.","Each creator looked up is billed whether it is kept or dropped; quote the creator lookups, not the plain page price.","author_country is the country the creator declares, not where the reel was filmed; topics about a place (travel, eSIMs) are often made by visitors."],"decision_table":[{"option":"Reels from creators who declare one market","endpoint":"instagram/search/reels","best_for":"country= keeps only that market's creators (ES, MX, DE, BR, KR, FR) and fills followers","cost":"per page, plus per creator looked up"},{"option":"Localised reel search without a guarantee","endpoint":"instagram/search/reels","best_for":"region= adds the market to the query at the plain page price; creators may be from anywhere","cost":"per page"},{"option":"Instagram profile search with declared country","endpoint":"instagram/search/profiles","best_for":"include=about fills author.ext.country on up to twelve rows of a profile search","cost":"per page, plus per row filled"},{"option":"TikTok creators by account region","endpoint":"tiktok/search/users","best_for":"country= with a wide list of markets, when TikTok fits the brief","cost":"per in-country row returned"},{"option":"Cross-platform creator discovery","endpoint":"search/creators","best_for":"Ranked creators with min_followers, but no country filter","cost":"flat per call"}],"cost":{"rows":[{"ref":"reels","id":"instagram/search/reels","runs":1,"hold_total":61}],"total":{"hold":61,"expected_min":1,"expected_max":61,"exact":true,"floor":false},"scaled":false}},{"id":"vet-a-creator","title":"Vet a creator before a partnership","when":["is this influencer legit","check a creator's engagement and brand safety","fake followers or controversy check"],"inputs":[{"name":"handle","description":"The creator's handle","example":"mkbhd"},{"name":"platform","description":"tiktok, youtube or instagram","example":"youtube"}],"steps":[{"id":"vet","endpoint":"prism/creator-vet","params":{"handle":"{handle}","platform":"{platform}"},"note":"Engagement rate, commenter quality, posting cadence and a judged brand-safety read with every flagged item linked to its source."}],"size":{"description":"one creator","items":1},"cheaper":[{"endpoint":"prism/creator-card","why":"Just the profile cards and follower totals across platforms, without the vetting."}],"pitfalls":["include=cross_platform adds the cross-platform identity check at a higher price; leave it off unless you need it.","Namesakes found in the news are excluded and counted in namesakes_excluded, not blamed on the creator."],"cost":{"rows":[{"ref":"vet","id":"prism/creator-vet","runs":1,"hold_total":50}],"total":{"hold":50,"expected_min":50,"expected_max":50,"exact":true,"floor":false},"scaled":false}},{"id":"creator-across-platforms","title":"One creator on every platform","when":["find this creator's TikTok, Instagram, YouTube and X","total followers across platforms","is this the same person on each platform"],"inputs":[{"name":"handle","description":"The handle to look up","example":"mrbeast"}],"steps":[{"id":"cards","endpoint":"prism/creator-card","params":{"handle":"{handle}","platforms":"tiktok,instagram,youtube,twitter","verify":"true"},"note":"verify=true adds an identity verdict per platform (same, possible, different) at the same price."}],"size":{"description":"one handle on four platforms","items":4},"deeper":[{"endpoint":"prism/find-accounts","why":"When the handle differs by platform: turn a name into ranked candidate accounts."}],"pitfalls":["A handle existing on a platform does not mean it is the same creator; without verify=true you only learn that the handle exists.","A null card means the handle was not found there; only a miss on every platform is refunded."],"cost":{"rows":[{"ref":"cards","id":"prism/creator-card","runs":1,"hold_total":5}],"total":{"hold":5,"expected_min":5,"expected_max":5,"exact":true,"floor":false},"scaled":false}},{"id":"creator-profile-posts-comments","title":"A creator's profile, recent posts and the comments on them","when":["get a creator's profile, latest videos and their comments","analyse a TikTok creator's recent content","comments on a creator's last videos"],"inputs":[{"name":"handle","description":"The TikTok handle","example":"charlidamelio"}],"steps":[{"id":"profile","endpoint":"tiktok/profile","params":{"handle":"{handle}"}},{"id":"videos","endpoint":"tiktok/profile/videos","params":{"handle":"{handle}"},"note":"Each row's post.url feeds the comments call."},{"id":"comments","endpoint":"tiktok/post/comments","params":{},"bind":{"url":"videos.items[].post.url"},"repeat":"per_item_of:videos","note":"One call per video you want comments for; pick the videos first rather than fanning out over the whole page."}],"size":{"description":"profile, one page of videos, first comment page on five videos","items":5},"cheaper":[{"endpoint":"tiktok/profile/full","why":"Profile, recent posts and computed engagement metrics in one call, without comments."}],"deeper":[{"endpoint":"prism/comments","why":"Every comment on one video, replies nested, in one call."}],"pitfalls":["The comments step is billed per video and per page; the fan-out, not the profile, is what grows the bill.","The same chain exists per platform: instagram/profile/posts then instagram/post/comments, youtube/channel/videos then youtube/video/comments."],"cost":{"rows":[{"ref":"profile","id":"tiktok/profile","runs":1,"hold_total":1},{"ref":"videos","id":"tiktok/profile/videos","runs":1,"hold_total":1},{"ref":"comments","id":"tiktok/post/comments","runs":5,"hold_total":5}],"total":{"hold":7,"expected_min":7,"expected_max":7,"exact":true,"floor":false},"scaled":false}},{"id":"find-accounts-for-a-name","title":"Find the social accounts of a person or company","when":["what are this company's social accounts","find a person's Instagram, TikTok, X and LinkedIn","I only have a name"],"inputs":[{"name":"name","description":"The person's or company's name","example":"Ogilvy"},{"name":"type","description":"person or company","example":"company"}],"steps":[{"id":"accounts","endpoint":"prism/find-accounts","params":{"name":"{name}","type":"{type}"},"note":"Ranked candidates per platform, each with a match level, for a person to review."}],"size":{"description":"one name","items":1},"deeper":[{"endpoint":"prism/creator-card","why":"Once you know the handle, cards and an identity verdict across platforms."}],"pitfalls":["The match level is a ranking for human review, not proof of identity.","Pass website= when you know the official domain: a verified account linking to it is taken as the match without judging."],"cost":{"rows":[{"ref":"accounts","id":"prism/find-accounts","runs":1,"hold_total":17}],"total":{"hold":17,"expected_min":2,"expected_max":17,"exact":true,"floor":false},"scaled":false}},{"id":"linkedin-member-profile","title":"A LinkedIn member's profile and recent posts","when":["LinkedIn profile and posts for a person","everything on someone's LinkedIn"],"inputs":[{"name":"profile_url","description":"The member's /in/ profile URL","example":"https://www.linkedin.com/in/williamhgates/"}],"steps":[{"id":"profile","endpoint":"linkedin/profile","params":{"url":"{profile_url}"},"note":"The canonical Author: name, headline (bio), location, exact followers and connections."},{"id":"posts","endpoint":"linkedin/profile/posts","params":{"url":"{profile_url}"},"note":"Recent posts as a canonical PostList, one fixed window; limit (up to 100) sets how many."}],"size":{"description":"one member, default post window","items":20},"cheaper":[{"endpoint":"linkedin/profile/with-posts","why":"Profile, counts, recent posts and background in one premium call instead of two."}],"deeper":[{"endpoint":"linkedin/profile/posts/archive","why":"The member's complete post history with exact times, billed per post returned."}],"pitfalls":["linkedin/profile/full is a COMPANY page composite; for a member /in/ URL it is the wrong endpoint.","linkedin/profile/posts has no next page: a cursor or page= is rejected. Above fifty posts the price is per post returned.","Experience, education and skills are not on linkedin/profile; use linkedin/profile/complete or linkedin/profile/all."],"decision_table":[{"option":"Identity and counts only","endpoint":"linkedin/profile","best_for":"Name, headline, location, followers, connections; the urn for sub-resources","cost":"flat per call"},{"option":"Recent posts only","endpoint":"linkedin/profile/posts","best_for":"Up to a hundred recent posts in one fixed window","cost":"flat up to fifty posts, then per post returned"},{"option":"Profile, counts and recent posts together","endpoint":"linkedin/profile/with-posts","best_for":"One call for a person card plus their latest posts and background","cost":"flat per call"},{"option":"Background without counts","endpoint":"linkedin/profile/complete","best_for":"Experience, education, skills and recommendations; followers are null","cost":"flat per call"},{"option":"Every section in one call","endpoint":"linkedin/profile/all","best_for":"A full audit: all background sections, interests, similar profiles, verified flag","cost":"per profile returned, up to ten profiles per call"},{"option":"Company page with posts and engagement metrics","endpoint":"linkedin/profile/full","best_for":"A /company/ URL only; never a member","cost":"flat per call"}],"cost":{"rows":[{"ref":"profile","id":"linkedin/profile","runs":1,"hold_total":5},{"ref":"posts","id":"linkedin/profile/posts","runs":1,"hold_total":5}],"total":{"hold":10,"expected_min":10,"expected_max":10,"exact":true,"floor":false},"scaled":false}},{"id":"linkedin-people-search","title":"Find LinkedIn members by role and company","when":["find marketing directors at a company on LinkedIn","LinkedIn people search with filters","build a list of prospects"],"inputs":[{"name":"keywords","description":"Search keywords","example":"head of marketing"}],"steps":[{"id":"people","endpoint":"linkedin/search/people","params":{"query":"{keywords}"},"note":"Ten members a page with handle, headline, location and the profile URL. Add include=profile (with limit for the top rows) to join exact follower and connection counts in the same call."},{"id":"background","endpoint":"linkedin/profile/complete","params":{},"bind":{"url":"people.items[].author.url"},"repeat":"per_item_of:people","note":"Only for the members you shortlist."}],"size":{"description":"one page of ten members, three backgrounds","items":3},"pitfalls":["On a plain search, author.followers is LinkedIn's rounded display bucket (author.ext.followers_approximate is true); include=profile makes it exact.","current_company and past_company take the numeric company id (author.id on linkedin/company), not a name."],"cost":{"rows":[{"ref":"people","id":"linkedin/search/people","runs":1,"hold_total":10},{"ref":"background","id":"linkedin/profile/complete","runs":3,"hold_total":30}],"total":{"hold":40,"expected_min":40,"expected_max":40,"exact":true,"floor":false},"scaled":false}},{"id":"batch-profiles","title":"Look up a list of handles in one call","when":["vet a spreadsheet of creator handles","follower counts for 50 accounts","bulk profile lookup across platforms"],"inputs":[{"name":"items","description":"JSON array of up to 50 {platform, handle, custom_id?}","example":"[{\"platform\":\"tiktok\",\"handle\":\"@scout2015\"},{\"platform\":\"instagram\",\"handle\":\"nasa\"}]"}],"steps":[{"id":"profiles","endpoint":"prism/profiles","method":"POST","params":{"items":"{items}"},"note":"One canonical Author per row in input order, with a status and the caller's custom_id echoed."}],"size":{"description":"fifty handles","items":50},"deeper":[{"endpoint":"prism/jobs","why":"Up to five thousand handles as one background job at the same per-row price."}],"pitfalls":["At most fifty items per call (twenty-five with include=posts); split larger lists or use prism/jobs.","Each row is priced at its platform's own rate (LinkedIn rows cost more); not_found, unsupported and errored rows are refunded.","Do not loop the single profile endpoints for a list: one batch call is cheaper to run and to retry."],"cost":{"rows":[{"ref":"profiles","id":"prism/profiles","runs":1,"hold_total":50}],"total":{"hold":50,"expected_min":1,"expected_max":50,"exact":false,"floor":false},"scaled":true}},{"id":"export-tiktok-comments","title":"Export the latest N comments on a TikTok video","when":["get/export/download comments on this TikTok","last 200 comments","TikTok comments to CSV"],"inputs":[{"name":"url","description":"The TikTok video URL","example":"https://www.tiktok.com/@stoolpresidente/video/7623818255903329566"}],"steps":[{"id":"comments","endpoint":"tiktok/post/comments","params":{"url":"{url}","sort":"recent","scan_pages":"3"},"repeat":"until_n_items","note":"Reads up to three pages per call and returns them newest first."}],"size":{"description":"two hundred comments","items":200},"cheaper":[{"endpoint":"prism/comments","why":"One call with max=N that pages to N for you, metered per comment page scanned."}],"pitfalls":["sort=recent sorts only what was read; TikTok has no native newest-first order, so raise scan_pages to read more of the thread.","The endpoint is tiktok/post/comments; tiktok/video/comments does not exist.","On prism/comments set max (the default is a thousand) and replies=false unless you want replies, or the hold is far larger than the job."],"cost":{"rows":[{"ref":"comments","id":"tiktok/post/comments","runs":5,"hold_total":15}],"total":{"hold":15,"expected_min":5,"expected_max":15,"exact":false,"floor":true},"scaled":false}},{"id":"all-comments-on-a-post","title":"Every comment on any post, in one call","when":["all comments on this YouTube video","scrape every comment on a Reddit thread","comments with replies on a post"],"inputs":[{"name":"url","description":"A TikTok, YouTube, Facebook, Reddit, Hacker News or Instagram post URL","example":"https://www.youtube.com/watch?v=dQw4w9WgXcQ"},{"name":"max_comments","description":"Stop after about this many top-level comments","example":"500"}],"steps":[{"id":"comments","endpoint":"prism/comments","params":{"url":"{url}","max":"{max_comments}","replies":"false"},"note":"Pages the thread server-side to max; replies=true nests replies where the platform has them."}],"size":{"description":"five hundred top-level comments","items":500},"cheaper":[{"endpoint":"youtube/video/comments","why":"One page of a single platform's comments, when you only need the first page."}],"pitfalls":["max drives the price: leave it at its default and a long thread is read to a thousand comments.","Whole pages are returned, so the count can slightly exceed max.","Instagram returns top-level comments only at a flat price; replies come from instagram/post/comment/replies, one call per parent with engagement.replies above zero.","sort=top on Instagram is the platform's own finite ranked head; use the default order to harvest the whole thread."],"cost":{"rows":[{"ref":"comments","id":"prism/comments","runs":1,"hold_total":10}],"total":{"hold":10,"expected_min":2,"expected_max":10,"exact":true,"floor":false},"scaled":false}},{"id":"label-comments","title":"Which comments are questions, complaints or buyers","when":["what are people saying under this post","find purchase intent in comments","complaints in the comments"],"inputs":[{"name":"url","description":"The TikTok video URL","example":"https://www.tiktok.com/@stoolpresidente/video/7623818255903329566"}],"steps":[{"id":"comments","endpoint":"tiktok/post/comments","params":{"url":"{url}","label":"question,complaint,purchase_intent"},"note":"Each comment carries computed.labels for the presets named."}],"size":{"description":"one page of comments","items":50},"deeper":[{"endpoint":"prism/comment-leads","why":"Buyer leads from the comments of every post a keyword search returns."}],"pitfalls":["sentiment, question, purchase_intent and complaint are free default labels; spam, toxic and low_quality are paid.","prism/comments takes no label= (an undeclared param is ignored); it judges the free presets on the first comments of each call by default.","SocialCrawl reads public data only: there is no endpoint that replies, posts or acts as the user."],"cost":{"rows":[{"ref":"comments","id":"tiktok/post/comments","runs":1,"hold_total":1}],"total":{"hold":1,"expected_min":1,"expected_max":1,"exact":true,"floor":false},"scaled":false}},{"id":"video-transcript","title":"Transcribe a video","when":["transcript of this YouTube video","what is said in this TikTok","get captions to summarise a video"],"inputs":[{"name":"url","description":"The YouTube video URL","example":"https://www.youtube.com/watch?v=dQw4w9WgXcQ"}],"steps":[{"id":"transcript","endpoint":"youtube/video/transcript","params":{"url":"{url}"}}],"size":{"description":"one video","items":1},"deeper":[{"endpoint":"youtube/transcripts","why":"Up to a hundred YouTube transcripts in one POST, by bare video id."},{"endpoint":"prism/video-intel","why":"Video detail, stats, top comments and (with include=transcript) the transcript for one video in one call."}],"pitfalls":["Each platform has its own transcript endpoint: tiktok/post/transcript, instagram/media/transcript, twitter/tweet/transcript, facebook/post/transcript.","youtube/transcripts takes bare eleven-character ids, not watch URLs."],"cost":{"rows":[{"ref":"transcript","id":"youtube/video/transcript","runs":1,"hold_total":3}],"total":{"hold":3,"expected_min":3,"expected_max":3,"exact":true,"floor":false},"scaled":false}},{"id":"compare-reviews-across-retailers","title":"Compare one product's reviews across retailers","when":["Amazon vs Walmart reviews for one product","compare ratings and complaints across stores","what buyers say about a product on different retailers"],"inputs":[{"name":"product","description":"The product name, as a shopper would search it","example":"Anker Soundcore Life Q30"}],"steps":[{"id":"amazon_search","endpoint":"amazon/product-search","params":{"query":"{product}","country":"US"},"note":"Pick the row that is the product itself; its product.id is the ASIN."},{"id":"amazon_reviews","endpoint":"amazon/reviews","params":{"country":"US"},"bind":{"asin":"amazon_search.items[].product.id"}},{"id":"walmart_search","endpoint":"walmart/search","params":{"query":"{product}"},"note":"product.id is the Walmart item id the reviews call takes."},{"id":"walmart_reviews","endpoint":"walmart/reviews","params":{},"bind":{"product_id":"walmart_search.items[].product.id"}}],"size":{"description":"first review page at two retailers","items":2},"deeper":[{"endpoint":"prism/product-reviews","why":"A themed pros-and-cons report across Amazon, Google Shopping and Trustpilot only."}],"pitfalls":["Never call a reviews endpoint with a guessed id: resolve the ASIN, item id, TCIN or SKU through that retailer's search first.","prism/product-reviews covers Amazon, Google Shopping and Trustpilot only; it has no Walmart, Target, Home Depot or Wayfair leg.","amazon/reviews returns one fixed page of on-page reviews (about eight) and does not page.","A Walmart id from one marketplace (US or CA) does not resolve in the other."],"decision_table":[{"option":"Report across Amazon, Google Shopping and Trustpilot","endpoint":"prism/product-reviews","best_for":"One themed pros-and-cons report over those three sources only","cost":"flat per call"},{"option":"Amazon","endpoint":"amazon/reviews","best_for":"On-page reviews by ASIN from amazon/product-search","cost":"per page"},{"option":"Walmart","endpoint":"walmart/reviews","best_for":"Reviews by item id from walmart/search, sortable and paged","cost":"per page"},{"option":"Target","endpoint":"target/reviews","best_for":"Reviews by TCIN from target/category or a product URL","cost":"per page"},{"option":"Home Depot","endpoint":"home_depot/reviews","best_for":"Reviews by item id from home_depot/search","cost":"per page"},{"option":"Wayfair","endpoint":"wayfair/reviews","best_for":"Reviews by SKU from wayfair/search","cost":"per page"},{"option":"Google Shopping","endpoint":"google_shopping/reviews","best_for":"Aggregated reviews by gid (product.ext.gid on google_shopping/product-search)","cost":"per page"},{"option":"TikTok Shop","endpoint":"tiktokshop/product/reviews","best_for":"Reviews of a TikTok Shop product by URL or product id","cost":"per page"},{"option":"Trustpilot (the business, not one product)","endpoint":"trustpilot/reviews","best_for":"Company reviews by domain","cost":"per page"}],"cost":{"rows":[{"ref":"amazon_search","id":"amazon/product-search","runs":1,"hold_total":1},{"ref":"amazon_reviews","id":"amazon/reviews","runs":1,"hold_total":5},{"ref":"walmart_search","id":"walmart/search","runs":1,"hold_total":5},{"ref":"walmart_reviews","id":"walmart/reviews","runs":1,"hold_total":5}],"total":{"hold":16,"expected_min":16,"expected_max":16,"exact":true,"floor":false},"scaled":false}},{"id":"home-depot-price-and-reviews","title":"A Home Depot product's price and reviews","when":["price and reviews for a drill at Home Depot","Home Depot product reviews","is this tool in stock and what do buyers say"],"inputs":[{"name":"product","description":"Product name or model number","example":"DEWALT 20V MAX cordless drill DCD771C2"}],"steps":[{"id":"search","endpoint":"home_depot/search","params":{"query":"{product}"},"note":"Each row has the item id, price, rating and stock; pick the matching model."},{"id":"reviews","endpoint":"home_depot/reviews","params":{},"bind":{"item_id":"search.items[].product.id"}}],"size":{"description":"one search page and the first review page","items":2},"pitfalls":["home_depot/search is the keyword-to-item-id resolver; never call home_depot/reviews with a guessed item_id.","A null price.current comes with product.ext.price_note (for example see final price in cart); prices are the online price.","prism/product-reviews and the amazon endpoints do not cover Home Depot."],"cost":{"rows":[{"ref":"search","id":"home_depot/search","runs":1,"hold_total":5},{"ref":"reviews","id":"home_depot/reviews","runs":1,"hold_total":5}],"total":{"hold":10,"expected_min":10,"expected_max":10,"exact":true,"floor":false},"scaled":false}},{"id":"product-review-report","title":"One report on a product's reviews across marketplaces","when":["pros and cons of a product from its reviews","summarise reviews across Amazon and Google Shopping","review themes for a product"],"inputs":[{"name":"product","description":"The product name","example":"AirPods Pro 3"}],"steps":[{"id":"report","endpoint":"prism/product-reviews","params":{"query":"{product}"},"note":"Resolves the product on Amazon, Google Shopping and Trustpilot, then returns per-source ratings, a retailer matrix and themed pros and cons."}],"size":{"description":"one product","items":1},"cheaper":[{"endpoint":"amazon/reviews","why":"One retailer's reviews when you already have the ASIN."}],"pitfalls":["Three sources only: Amazon, Google Shopping and Trustpilot. For Walmart, Target, Home Depot or Wayfair, chain that retailer's search and reviews.","Anchor with asin= or gid= for precision; the gid is product.ext.gid, not the catalog id.","Commerce sources are slow: allow tens of seconds per call."],"cost":{"rows":[{"ref":"report","id":"prism/product-reviews","runs":1,"hold_total":30}],"total":{"hold":30,"expected_min":30,"expected_max":30,"exact":true,"floor":false},"scaled":false}},{"id":"app-store-reviews","title":"Reviews of a mobile app","when":["App Store reviews for an app","what users complain about in our app","Google Play and App Store ratings"],"inputs":[{"name":"app","description":"The app name","example":"Spotify"}],"steps":[{"id":"search","endpoint":"app_store/app-search","params":{"query":"{app}"},"note":"app.id is the numeric App Store id the reviews call takes."},{"id":"reviews","endpoint":"app_store/app-reviews","params":{"sort_by":"most_recent"},"bind":{"app_id":"search.items[].app.id"}}],"size":{"description":"one app, first review page","items":1},"deeper":[{"endpoint":"prism/app-reviews","why":"Both stores at once, translated, clustered and sentiment-scored."}],"pitfalls":["The two stores use different ids: a numeric id on the App Store, a package name (com.spotify.music) on Google Play; resolve each through its own app-search.","The same chain on Google Play is google_play/app-search then google_play/app-reviews."],"cost":{"rows":[{"ref":"search","id":"app_store/app-search","runs":1,"hold_total":5},{"ref":"reviews","id":"app_store/app-reviews","runs":1,"hold_total":5}],"total":{"hold":10,"expected_min":10,"expected_max":10,"exact":true,"floor":false},"scaled":false}},{"id":"local-business-reviews","title":"Reviews of a local business","when":["Yelp reviews for a restaurant","what customers say about a shop","reviews of businesses near a location"],"inputs":[{"name":"business","description":"Business name or category","example":"pizza"},{"name":"location","description":"City or neighbourhood","example":"New York, NY"}],"steps":[{"id":"search","endpoint":"yelp/search","params":{"query":"{business}","location":"{location}"},"note":"place.id is the business encid the reviews call takes."},{"id":"reviews","endpoint":"yelp/business/reviews","params":{},"bind":{"id":"search.items[].place.id"}}],"size":{"description":"one search page, one business's first review page","items":1},"cheaper":[{"endpoint":"google/business/extended-reviews","why":"Google's reviews for one business by name, with no search step."}],"pitfalls":["Yelp alias slugs (prince-street-pizza-new-york-2) are not accepted; use the encid from yelp/search.","For hotels and attractions use the tripadvisor endpoints."],"cost":{"rows":[{"ref":"search","id":"yelp/search","runs":1,"hold_total":1},{"ref":"reviews","id":"yelp/business/reviews","runs":1,"hold_total":5}],"total":{"hold":6,"expected_min":6,"expected_max":6,"exact":true,"floor":false},"scaled":false}},{"id":"competitor-ads","title":"See the ads a competitor is running","when":["what ads is a competitor running","Facebook ads of a brand","ad library search"],"inputs":[{"name":"company","description":"The advertiser's name","example":"Lululemon"}],"steps":[{"id":"ads","endpoint":"facebook/adlibrary/company/ads","params":{"companyName":"{company}","status":"ACTIVE"},"note":"Active ads in the public Facebook ad library for that advertiser."}],"size":{"description":"one page of ads","items":1},"cheaper":[{"endpoint":"facebook/adlibrary/search/ads","why":"Keyword search of the ad library when you do not know the advertiser."}],"pitfalls":["Pass pageId instead of companyName when several pages share the name.","Each network has its own library; see the decision table."],"decision_table":[{"option":"Facebook and Instagram","endpoint":"facebook/adlibrary/company/ads","best_for":"One advertiser's ads by name or page id, with status and media filters","cost":"per page"},{"option":"Google (Search, YouTube, Maps, Play, Shopping)","endpoint":"google/company/ads","best_for":"One advertiser's ads by domain or advertiser id","cost":"per page"},{"option":"LinkedIn","endpoint":"linkedin/ads/search","best_for":"A company's or a keyword's LinkedIn ads","cost":"per page"},{"option":"TikTok","endpoint":"tiktok/adlibrary/search","best_for":"Ads by keyword or advertiser name","cost":"per page"}],"cost":{"rows":[{"ref":"ads","id":"facebook/adlibrary/company/ads","runs":1,"hold_total":5}],"total":{"hold":5,"expected_min":5,"expected_max":5,"exact":true,"floor":false},"scaled":false}},{"id":"track-a-creator-daily","title":"Track a creator's new posts every day","when":["poll a creator's new posts daily","alert me when this account posts","only fetch posts I do not have yet"],"inputs":[{"name":"handle","description":"The Instagram handle","example":"instagram"},{"name":"webhook_url","description":"HTTPS URL that receives each run","example":"https://example.com/hooks/socialcrawl"},{"name":"last_run_date","description":"Date of your previous run, YYYY-MM-DD; leave since out on the first run","example":"2026-09-30"}],"steps":[{"id":"posts","endpoint":"instagram/profile/posts","params":{"handle":"{handle}","since":"{last_run_date}"},"note":"Run by hand with the date of your last run; the page that reaches since ends the walk, so you stop paying for posts you already hold. Do not copy a fixed last_run_date into the monitor: its setup uses since=now-1d."}],"setup":[{"method":"POST","path":"/v1/monitors","body":{"recipe":"instagram/profile/posts","params":{"handle":"{handle}","since":"now-1d"},"cadence":"daily","webhook_url":"{webhook_url}","track":{"metrics":["items[].post.engagement.likes"]},"alert_rules":[{"metric":"rows_new","op":"gt","value":0}],"suppress_webhook_unless_alert":true},"note":"Runs the read every day with since set to yesterday and posts to your webhook only when a run has a post the previous run did not. Create is free and returns estimated_cost_per_run and next_run_at; there is no immediate first run."}],"size":{"description":"one page per day","items":1},"pitfalls":["since stops the walk; it does not make the page that reaches it free.","Pinned posts sit out of date order and never end the walk.","A scheduled run bills the read's own price plus a small scheduling premium; /v1/monitors returns estimated_cost_per_run and estimated_monthly_cost on create."],"cost":{"rows":[{"ref":"posts","id":"instagram/profile/posts","runs":1,"hold_total":1}],"total":{"hold":1,"expected_min":1,"expected_max":1,"exact":true,"floor":false},"scaled":false,"per_run":{"hold":2,"expected_min":2,"recipe":"instagram/profile/posts"},"recurring":{"kind":"monitor","per":2,"perDay":1,"cadence":"1 run per day","unit":"day"}}},{"id":"youtube-competitor-monitor","title":"Weekly alert on a competitor's new YouTube videos","when":["weekly YouTube competitor monitor","alert on new videos from a channel","watch a competitor's uploads"],"inputs":[{"name":"handle","description":"The channel handle","example":"mkbhd"},{"name":"webhook_url","description":"HTTPS URL that receives each run","example":"https://example.com/hooks/socialcrawl"},{"name":"last_run_date","description":"Date of the previous run, YYYY-MM-DD","example":"2026-09-25"}],"steps":[{"id":"videos","endpoint":"youtube/channel/videos","params":{"handle":"{handle}","since":"{last_run_date}"},"note":"The read the monitor replays; run it by hand to see what one run returns. Do not copy a fixed last_run_date into the monitor: its setup uses since=now-7d."}],"setup":[{"method":"POST","path":"/v1/monitors","body":{"recipe":"youtube/channel/videos","params":{"handle":"{handle}","since":"now-7d"},"cadence":"weekly","webhook_url":"{webhook_url}","track":{"metrics":["items[].post.engagement.views"]},"alert_rules":[{"metric":"rows_new","op":"gt","value":0}],"suppress_webhook_unless_alert":true},"note":"Each weekly run reads the uploads of the last seven days and posts to your webhook only when it holds a video the previous run did not; the first run has nothing to compare and stays quiet."}],"size":{"description":"one page per week","items":1},"pitfalls":["Do not build your own cron or polling loop: /v1/monitors schedules any registered GET read and delivers to a signed webhook.","/v1/web/monitors is a different family that watches one web page; it is not for a channel's uploads.","since requires sort=latest on this endpoint (filled in when sort is absent).","Alert on new videos with the rows_new alert (gt 0) on a track monitor, not on a numeric threshold; deltas.rows_new lists the new ids."],"cost":{"rows":[{"ref":"videos","id":"youtube/channel/videos","runs":1,"hold_total":1}],"total":{"hold":1,"expected_min":1,"expected_max":1,"exact":true,"floor":false},"scaled":false,"per_run":{"hold":2,"expected_min":2,"recipe":"youtube/channel/videos"},"recurring":{"kind":"monitor","per":2,"perDay":0.14285714285714285,"cadence":"1 run per week","unit":"week"}}},{"id":"web-page-change-alert","title":"Alert when a web page changes","when":["alert me when a pricing page changes","watch a URL for changes every 15 minutes","monitor a competitor's web page"],"inputs":[{"name":"page_url","description":"The page to watch","example":"https://example.com/pricing"},{"name":"cadence_minutes","description":"Minutes between checks: 5 to 60, or whole hours","example":"15"},{"name":"webhook_url","description":"HTTPS URL that receives a signed callback on each check","example":"https://example.com/hooks/socialcrawl"}],"steps":[{"id":"monitor","endpoint":"web/monitors","method":"POST","params":{"url":"{page_url}","cadence_minutes":"{cadence_minutes}","webhook_url":"{webhook_url}"},"note":"Creating the monitor is free; data.monitor_id names it."},{"id":"checks","endpoint":"web/monitors/{monitor_id}/checks","params":{},"bind":{"monitor_id":"monitor.monitor_id"},"note":"Reading the checks is free; the webhook means you rarely need to."}],"size":{"description":"one day of checks every fifteen minutes","items":96},"pitfalls":["Creating is free but every check bills the page read plus an orchestration premium: quote checks per day (1440 / cadence_minutes) times the per-check price.","/v1/monitors (recipe monitors, one-hour floor) is the wrong family for one page; /v1/web/monitors checks as often as every five minutes.","The change judge is on by default, so you are notified on meaningful changes rather than every byte-level diff; pass goal= to say what matters."],"cost":{"rows":[{"ref":"monitor","id":"web/monitors","runs":1,"hold_total":0},{"ref":"checks","id":"web/monitors/{monitor_id}/checks","runs":1,"hold_total":0}],"total":{"hold":0,"expected_min":0,"expected_max":0,"exact":true,"floor":false},"scaled":false,"recurring":{"kind":"web","per":2,"perDay":96,"cadence":"96 checks per day","unit":"day"}}},{"id":"bulk-url-stats","title":"Engagement stats for a list of post URLs","when":["views, likes and comments for 500 URLs","refresh stats for a spreadsheet of post links","verify clipper payouts"],"inputs":[{"name":"urls","description":"JSON array of up to 100 post URLs, any mix of platforms","example":"[\"https://www.youtube.com/watch?v=dQw4w9WgXcQ\",\"https://www.tiktok.com/@stoolpresidente/video/7623818255903329566\"]"}],"steps":[{"id":"stats","endpoint":"prism/post-stats","method":"POST","params":{"urls":"{urls}"},"note":"One row per URL in input order: platform, status, views, likes, comments, shares, saves and fetched_at. Send larger lists in chunks of a hundred."}],"size":{"description":"five hundred URLs in chunks of a hundred","items":500},"deeper":[{"endpoint":"prism/jobs","why":"Up to five thousand URLs as one background job at the same per-URL price, with a webhook when it completes."}],"pitfalls":["At most a hundred URLs per call: five hundred URLs is five calls, or one prism/jobs job.","Each URL is priced at its platform's own rate (Instagram and LinkedIn cost more than TikTok and YouTube); quote per platform, not one flat rate per URL.","Dead, errored and unsupported URLs are refunded; one bad link never fails the batch.","Do not loop the single-post endpoints: it is slower and no cheaper."],"cost":{"rows":[{"ref":"stats","id":"prism/post-stats","runs":5,"hold_total":500}],"total":{"hold":500,"expected_min":5,"expected_max":500,"exact":false,"floor":false},"scaled":true}},{"id":"cohort-keyword-matches","title":"Which of my accounts posted about a keyword","when":["which of our customers' accounts posted about our brand","search only the handles in my CSV for a keyword","did any of these creators mention us last month"],"inputs":[{"name":"cohort_name","description":"A label for the list","example":"Q3 customers"},{"name":"members","description":"JSON array of {platform, handle, external_id}, up to a thousand per upload","example":"[{\"platform\":\"tiktok\",\"handle\":\"mrbeast\",\"external_id\":\"cust_001\"},{\"platform\":\"twitter\",\"handle\":\"nasa\",\"external_id\":\"cust_002\"}]","type":"json"},{"name":"keywords","description":"JSON array of one to twenty keywords","example":"[\"acme\"]","type":"json"},{"name":"date_from","description":"Window start as a full RFC3339 timestamp","example":"2026-09-01T00:00:00.000Z"},{"name":"date_to","description":"Window end as a full RFC3339 timestamp","example":"2026-09-30T23:59:59.999Z"},{"name":"max_pages","description":"Page budget for each feed a member is read from, one to twenty; a feed with no next page reads one page whatever you set","example":"2","type":"json"},{"name":"max_credits","description":"Safety limit: the query is rejected when its computed ceiling is above it","example":"400","type":"json"}],"steps":[],"setup":[{"method":"POST","path":"/v1/cohorts","body":{"name":"{cohort_name}"},"note":"Free. Send an Idempotency-Key header holding a UUID; data.id is the cohortId."},{"method":"PUT","path":"/v1/cohorts/{cohortId}/members","body":{"members":"{members}"},"note":"Free. One chunk per call with its own Idempotency-Key; external_id comes back on every match so you can join results to your records."},{"method":"POST","path":"/v1/cohorts/{cohortId}/queries","body":{"keywords":"{keywords}","date_from":"{date_from}","date_to":"{date_to}","max_pages_per_identity":"{max_pages}","max_items_per_identity":200,"max_credits":"{max_credits}"},"note":"Holds the full computed ceiling (estimated_credits) up front and runs in the background; data.query_id is the queryId."},{"method":"GET","path":"/v1/cohort-queries/{queryId}","note":"Free. Poll until status is terminal: succeeded, failed, cancelled or expired."},{"method":"GET","path":"/v1/cohort-queries/{queryId}/results","note":"Free, and only once status is succeeded (any other status is a 409). One row per matching member with its external_id and matched keywords, plus coverage per member."}],"size":{"description":"two hundred accounts, two pages each","items":200},"pitfalls":["Do not search the whole platform (prism/brand-mentions, search/everywhere) or loop each handle's posts endpoint: a cohort query reads only your accounts and caps the spend.","date_from and date_to are full RFC3339 timestamps with an offset; a bare YYYY-MM-DD is a 400.","The hold is always the full computed ceiling (estimated_credits). max_credits is only a guard: a ceiling above it rejects the query before anything is held. The unused hold is refunded when the query ends, and a 402 means your balance (or the key's spend cap) is below the ceiling.","The ceiling counts each member at its platform's price: X, TikTok, Kwai and Truth Social cost a page price times max_pages, Instagram and YouTube twice that; LinkedIn, Bluesky, Threads and Twitch ignore the page budget and cost a fixed amount per member, and LinkedIn is the most expensive.","A feed with no next page reads exactly one page whatever max_pages says; naming platforms in the query is the other way to cut the ceiling.","POST and PUT need an Idempotency-Key UUID header; everything is scoped to the API key, not the account.","Results are served only when status is succeeded, and succeeded is not exhaustive: read each member's coverage.","Facebook and Snapchat accounts are rejected at upload; ten platforms are supported."],"cost":{"rows":[],"scaled":false}},{"id":"salary-and-open-roles","title":"Pay for a role in a country, and the open jobs","when":["what do senior data engineers earn in Germany","salary range and open remote jobs","job listings for a title"],"inputs":[{"name":"title","description":"The job title","example":"senior data engineer"},{"name":"country_code","description":"ISO 3166-1 alpha-2 country code","example":"de"},{"name":"location","description":"City or country for the listings","example":"Germany"}],"steps":[{"id":"salary","endpoint":"jobs/salary","params":{"query":"{title}","country_code":"{country_code}"},"note":"The pay band for the title in that country."},{"id":"listings","endpoint":"jobs/linkedin/search","params":{"query":"{title}","location":"{location}","workplace_types":"remote"},"note":"One page of listings; follow cursor for more."}],"size":{"description":"one salary lookup and one page of listings","items":2},"cheaper":[{"endpoint":"jobs/salary/titles","why":"Find the job title the salary data knows before you look it up."}],"pitfalls":["Listing rows carry a salary only when the board publishes one; the pay band comes from jobs/salary.","The listing searches are premium endpoints, priced well above the salary lookup.","jobs/bing/search needs location on its first page; jobs/indeed/search takes country_code.","workplace_types, employment_types and experience_levels are semicolon-separated."],"cost":{"rows":[{"ref":"salary","id":"jobs/salary","runs":1,"hold_total":1},{"ref":"listings","id":"jobs/linkedin/search","runs":1,"hold_total":10}],"total":{"hold":11,"expected_min":11,"expected_max":11,"exact":true,"floor":false},"scaled":false}},{"id":"stock-quote-and-news","title":"A stock's current price and latest headlines","when":["current price of NVIDIA stock and its news","stock quote and headlines","how is a company's share price doing"],"inputs":[{"name":"company","description":"Company or instrument name","example":"NVIDIA"}],"steps":[{"id":"ticker","endpoint":"finance/ticker-search","params":{"keyword":"{company}"},"note":"quote.id is the TICKER:EXCHANGE form (NVDA:NASDAQ) the quote call takes."},{"id":"quote","endpoint":"finance/quote","params":{},"bind":{"keyword":"ticker.items[].quote.id"}},{"id":"news","endpoint":"finance/news","params":{},"bind":{"keyword":"ticker.items[].quote.id"},"note":"Recent articles for the instrument, as a NewsArticleList."}],"size":{"description":"one instrument","items":1},"pitfalls":["Every finance endpoint takes keyword, not ticker= or symbol=.","Pass finance/quote the TICKER:EXCHANGE id from finance/ticker-search, not the company name.","finance/news takes the instrument directly; google_news/search and search/news are for topics, not tickers."],"cost":{"rows":[{"ref":"ticker","id":"finance/ticker-search","runs":1,"hold_total":1},{"ref":"quote","id":"finance/quote","runs":1,"hold_total":5},{"ref":"news","id":"finance/news","runs":1,"hold_total":1}],"total":{"hold":7,"expected_min":7,"expected_max":7,"exact":true,"floor":false},"scaled":false}},{"id":"crawl-site-to-markdown","title":"Crawl a site and get each page as markdown","when":["crawl the first 50 pages of a docs site","download a website as markdown","scrape every page under a path"],"inputs":[{"name":"site_url","description":"Root URL to crawl","example":"https://docs.example.com/"},{"name":"max_pages","description":"Most pages to crawl","example":"50"}],"steps":[{"id":"crawl","endpoint":"web/crawl","method":"POST","params":{"url":"{site_url}","limit":"{max_pages}","formats":"markdown"},"note":"An async job: the response carries job_id and the credits held for limit pages."},{"id":"result","endpoint":"web/jobs/{job_id}","params":{},"bind":{"job_id":"crawl.job_id"},"note":"Poll until status is completed (or pass webhook_url on the crawl); reading the job is free."}],"size":{"description":"fifty pages","items":50},"cheaper":[{"endpoint":"web/map","why":"List the site's URLs first, then crawl only the paths you need."}],"pitfalls":["Always set limit: the crawl holds limit pages up front (ten by default) and refunds the pages it did not crawl.","include_paths is the cheapest way to narrow a crawl; allow_external_links makes limit the only bound.","Do not loop web/scrape over every page; one crawl job is the same per-page price with one call to manage."],"cost":{"rows":[{"ref":"crawl","id":"web/crawl","runs":1,"hold_total":50},{"ref":"result","id":"web/jobs/{job_id}","runs":1,"hold_total":0}],"total":{"hold":50,"expected_min":1,"expected_max":50,"exact":true,"floor":false},"scaled":false}},{"id":"extract-from-a-page","title":"Pull structured fields from a web page","when":["extract the prices from this page","get the plan names and features from a pricing page","turn a web page into JSON"],"inputs":[{"name":"page_url","description":"The page to read","example":"https://example.com/pricing"},{"name":"prompt","description":"What to extract, in plain words","example":"Each plan's name, monthly price and included seats"}],"steps":[{"id":"extract","endpoint":"web/extract","params":{"url":"{page_url}","prompt":"{prompt}"}}],"size":{"description":"one page","items":1},"cheaper":[{"endpoint":"web/scrape","why":"The page as markdown, when you will read it yourself."}],"pitfalls":["Pass schema= (a JSON schema) instead of prompt= when you need fixed field names.","For changes to the same page over time, use the web-page-change-alert recipe instead of re-extracting."],"cost":{"rows":[{"ref":"extract","id":"web/extract","runs":1,"hold_total":5}],"total":{"hold":5,"expected_min":5,"expected_max":5,"exact":true,"floor":false},"scaled":false}},{"id":"korea-consumer-pulse","title":"What Korean consumers say about a product, and search interest","when":["what are Korean consumers saying about a product","Korean news, blogs and cafe posts about a brand","Korean search interest over the last year"],"inputs":[{"name":"keyword","description":"The keyword, in Korean","example":"불닭볶음면"}],"steps":[{"id":"posts","endpoint":"naver/brief","params":{"query":"{keyword}","corpora":"news,blog,cafearticle"},"note":"One query across the Naver corpora you name; include=digest adds an English digest with translated quotes."},{"id":"trend","endpoint":"naver/search-trend","params":{"keywords":"{keyword}","time_unit":"month"},"note":"Twelve months by default; the series is relative search volume."}],"size":{"description":"one brief and one trend series","items":2},"cheaper":[{"endpoint":"naver/blog/search","why":"One Naver corpus only (also naver/news/search, naver/cafearticle/search)."}],"deeper":[{"endpoint":"prism/korea-gap","why":"What Korea says about a topic against what the rest of the web says."}],"pitfalls":["Search in Korean: translating the keyword to English misses most Korean posts.","naver/search-trend takes keywords, not query, and sums several keywords into ONE series; call it once per term to compare.","Western indexes (google_trends, tiktok/search) miss most Korean search; use the Naver endpoints."],"cost":{"rows":[{"ref":"posts","id":"naver/brief","runs":1,"hold_total":10},{"ref":"trend","id":"naver/search-trend","runs":1,"hold_total":5}],"total":{"hold":15,"expected_min":15,"expected_max":15,"exact":true,"floor":false},"scaled":false}}];
